import { AnimatePresence, motion } from 'framer-motion';
import { useState } from 'react';

const posts = [
  { tag: 'Emotional Healing', icon: '💗', title: 'How to Begin Healing When You Feel Broken', date: 'April 15, 2025', read: '5 min', color: '#EDD5D0', desc: 'When everything feels shattered, the path to wholeness begins with one small act of self-compassion. This guide walks you gently through where to start.' },
  { tag: 'Anxiety', icon: '🕊️', title: 'Understanding Anxiety: Your Body\'s Protective Alarm', date: 'March 28, 2025', read: '6 min', color: '#D4DCCF', desc: 'Anxiety is not your enemy. When we learn to listen to what it\'s trying to tell us, it transforms from a threat into a teacher.' },
  { tag: 'Self-Love', icon: '🌸', title: 'The Art of Being Gentle With Yourself', date: 'March 12, 2025', read: '4 min', color: '#DDB7B0', desc: 'Self-compassion is not weakness — it is the foundation of true healing. Discover how to soften your inner voice and befriend yourself.' },
  { tag: 'Mindfulness', icon: '🧘', title: 'Five Grounding Practices for Overwhelming Days', date: 'February 22, 2025', read: '7 min', color: '#EAD9A8', desc: 'When the world feels too loud and too fast, these five simple practices bring you back to your body, your breath, and the present moment.' },
  { tag: 'Burnout', icon: '🌿', title: 'Recognizing Burnout Before It Breaks You', date: 'February 8, 2025', read: '5 min', color: '#D4DCCF', desc: 'Burnout whispers before it screams. Learn the early signs and how to tend to yourself before exhaustion becomes a crisis.' },
  { tag: 'Journaling', icon: '📖', title: 'Journaling as a Path to Emotional Clarity', date: 'January 30, 2025', read: '4 min', color: '#EDD5D0', desc: 'The blank page holds no judgment. Discover how a simple journaling practice can become your most powerful emotional processing tool.' },
  { tag: 'Emotional Intelligence', icon: '✨', title: 'What Emotional Intelligence Really Means', date: 'January 15, 2025', read: '6 min', color: '#DDB7B0', desc: 'Emotional intelligence is the quiet superpower that transforms how we relate to ourselves and others. Here\'s how to cultivate it gently.' },
  { tag: 'Grief', icon: '🕯️', title: 'Holding Grief: A Letter to Anyone Who is Hurting', date: 'January 2, 2025', read: '3 min', color: '#EAD9A8', desc: 'Grief is love with nowhere to go. This is a gentle letter for anyone navigating loss of any kind — reminding you that your grief is valid.' },
];

const allTags = ['All', ...Array.from(new Set(posts.map(p => p.tag)))];

/* ── Shared dark button ── */
const darkBtnStyle = {
  background: 'linear-gradient(135deg, #2C1E28, #3D2B38)',
  color: '#F5EDE8',
  border: '1px solid rgba(255,255,255,0.08)',
  borderRadius: '6px',
  padding: '13px 32px',
  fontFamily: 'Manrope',
  fontSize: '0.82rem',
  fontWeight: 700,
  letterSpacing: '0.07em',
  textTransform: 'uppercase',
  cursor: 'pointer',
  boxShadow: '0 4px 18px rgba(44,30,40,0.3)',
};

const BlogPage = () => {
  const [activeTag, setActiveTag] = useState('All');
  const [email, setEmail] = useState('');
  const [subscribed, setSubscribed] = useState(false);

  const filtered = activeTag === 'All' ? posts : posts.filter(p => p.tag === activeTag);

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>

      {/* ── Hero ── */}
      <section style={{ padding: '140px 2rem 70px', textAlign: 'center', position: 'relative', zIndex: 2, overflow: 'hidden' }}>
        {/* Bg blobs */}
        <div style={{
          position: 'absolute', top: '-60px', left: '50%', transform: 'translateX(-50%)',
          width: '700px', height: '400px',
          background: 'radial-gradient(ellipse, rgba(221,183,176,0.12) 0%, transparent 70%)',
          pointerEvents: 'none', zIndex: 1,
        }} />

        <motion.div initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.8 }} style={{ position: 'relative', zIndex: 2 }}>

          {/* Eyebrow */}
          <div style={{
            display: 'inline-flex', alignItems: 'center', gap: '0.6rem',
            fontFamily: 'Manrope', fontSize: '0.72rem', letterSpacing: '0.18em',
            color: '#8A7070', textTransform: 'uppercase', marginBottom: '1.2rem',
          }}>
            <span style={{ display: 'inline-block', width: '24px', height: '1px', background: '#C4A89E' }} />
            Resources & Reflections
            <span style={{ display: 'inline-block', width: '24px', height: '1px', background: '#C4A89E' }} />
          </div>

          <h1 style={{
            fontFamily: 'Cormorant Garamond, serif',
            fontSize: 'clamp(2.6rem, 5.5vw, 4.2rem)',
            fontWeight: 600, color: '#2C1E28', lineHeight: 1.18,
            marginBottom: '1.2rem', letterSpacing: '-0.01em',
          }}>
            Healing Reads
          </h1>

          <p style={{
            fontFamily: 'Manrope', fontSize: '1rem', color: '#7A606E',
            lineHeight: 1.9, maxWidth: '500px', margin: '0 auto 2rem',
          }}>
            Thoughtful articles, gentle guides, and emotional wisdom — written with love,
            for souls on a healing journey.
          </p>

          {/* Post count pill */}
          <div style={{
            display: 'inline-flex', alignItems: 'center', gap: '0.5rem',
            background: '#2C1E28', color: '#EDD5D0',
            borderRadius: '50px', padding: '6px 18px',
            fontFamily: 'Manrope', fontSize: '0.72rem', fontWeight: 700,
            letterSpacing: '0.08em', textTransform: 'uppercase',
          }}>
            <span style={{ width: '6px', height: '6px', borderRadius: '50%', background: '#EDD5D0', display: 'inline-block' }} />
            {posts.length} Articles
          </div>
        </motion.div>
      </section>

      {/* ── Featured Post ── */}
      <section style={{ padding: '0 2rem 60px', position: 'relative', zIndex: 2 }}>
        <div style={{ maxWidth: '1100px', margin: '0 auto' }}>
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            whileHover={{ y: -5, boxShadow: '0 24px 60px rgba(44,30,40,0.1)' }}
            style={{
              background: 'rgba(255,253,252,0.9)',
              backdropFilter: 'blur(20px)',
              border: '1px solid rgba(221,183,176,0.25)',
              borderRadius: '20px',
              padding: 'clamp(2rem, 4vw, 3.2rem)',
              cursor: 'pointer',
              transition: 'all 0.35s ease',
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
              gap: '2.5rem',
              alignItems: 'center',
              boxShadow: '0 2px 30px rgba(44,30,40,0.05)',
              borderLeft: '4px solid #2C1E28',
            }}
          >
            <div>
              {/* Featured badge — dark */}
              <div style={{
                display: 'inline-flex', alignItems: 'center', gap: '0.4rem',
                background: '#2C1E28',
                borderRadius: '4px',
                padding: '5px 14px',
                fontFamily: 'Manrope',
                fontSize: '0.68rem',
                color: '#EDD5D0',
                marginBottom: '1.2rem',
                fontWeight: 700,
                letterSpacing: '0.1em',
                textTransform: 'uppercase',
              }}>
                ✦ Featured Article
              </div>

              <h2 style={{
                fontFamily: 'Cormorant Garamond, serif',
                fontSize: 'clamp(1.5rem, 3vw, 2.2rem)',
                fontWeight: 600, color: '#2C1E28', lineHeight: 1.28, marginBottom: '1rem',
              }}>
                How to Begin Healing When You Feel Broken
              </h2>

              <p style={{ fontFamily: 'Manrope', fontSize: '0.9rem', color: '#7A606E', lineHeight: 1.85, marginBottom: '1.8rem' }}>
                When everything feels shattered, the path to wholeness begins with one small act
                of self-compassion. This guide walks you gently through where to start when you
                don't know where to begin.
              </p>

              <div style={{ display: 'flex', gap: '1.5rem', alignItems: 'center', marginBottom: '1.8rem' }}>
                <span style={{ fontFamily: 'Manrope', fontSize: '0.75rem', color: '#A89098' }}>April 15, 2025</span>
                <span style={{ width: '3px', height: '3px', borderRadius: '50%', background: '#C4A89E', display: 'inline-block' }} />
                <span style={{ fontFamily: 'Manrope', fontSize: '0.75rem', color: '#A89098' }}>5 min read</span>
              </div>

              <motion.button
                whileHover={{ scale: 1.03, boxShadow: '0 8px 28px rgba(44,30,40,0.4)' }}
                whileTap={{ scale: 0.97 }}
                style={darkBtnStyle}
              >
                Read Article →
              </motion.button>
            </div>

            {/* Quote panel */}
            <div style={{
              background: 'linear-gradient(135deg, rgba(237,213,208,0.25), rgba(212,220,207,0.2))',
              border: '1px solid rgba(221,183,176,0.2)',
              borderRadius: '16px',
              padding: '2.2rem',
              textAlign: 'center',
            }}>
              <div style={{ fontSize: '4.5rem', marginBottom: '1rem', lineHeight: 1 }}>💗</div>
              <div style={{
                fontFamily: 'Cormorant Garamond, serif',
                fontSize: '1.08rem',
                fontStyle: 'italic',
                color: '#5A3D4A',
                lineHeight: 1.75,
              }}>
                "Healing doesn't mean the damage never existed. It means the damage no longer controls your life."
              </div>
            </div>
          </motion.div>
        </div>
      </section>

      {/* ── Category Filter ── */}
      <section style={{ padding: '0 2rem 40px', position: 'relative', zIndex: 2 }}>
        <div style={{ maxWidth: '1100px', margin: '0 auto' }}>
          <div style={{ display: 'flex', gap: '0.6rem', flexWrap: 'wrap', alignItems: 'center' }}>
            <span style={{
              fontFamily: 'Manrope', fontSize: '0.72rem', letterSpacing: '0.12em',
              color: '#A89098', textTransform: 'uppercase', marginRight: '0.4rem',
            }}>
              Filter:
            </span>
            {allTags.map(tag => (
              <motion.button
                key={tag}
                whileTap={{ scale: 0.96 }}
                onClick={() => setActiveTag(tag)}
                style={{
                  background: activeTag === tag ? '#2C1E28' : 'rgba(255,253,252,0.8)',
                  color: activeTag === tag ? '#EDD5D0' : '#7A606E',
                  border: activeTag === tag ? '1px solid #2C1E28' : '1px solid rgba(221,183,176,0.3)',
                  borderRadius: '5px',
                  padding: '7px 16px',
                  fontFamily: 'Manrope',
                  fontSize: '0.75rem',
                  fontWeight: 600,
                  letterSpacing: '0.05em',
                  cursor: 'pointer',
                  transition: 'all 0.2s ease',
                  boxShadow: activeTag === tag ? '0 3px 14px rgba(44,30,40,0.25)' : 'none',
                }}
              >
                {tag}
              </motion.button>
            ))}

            {/* Post count */}
            <div style={{ marginLeft: 'auto', fontFamily: 'Manrope', fontSize: '0.75rem', color: '#A89098' }}>
              {filtered.length} article{filtered.length !== 1 ? 's' : ''}
            </div>
          </div>
        </div>
      </section>

      {/* ── Post Grid ── */}
      <section style={{ padding: '0 2rem 80px', position: 'relative', zIndex: 2 }}>
        <div style={{ maxWidth: '1100px', margin: '0 auto' }}>
          <AnimatePresence mode="wait">
            <motion.div
              key={activeTag}
              initial={{ opacity: 0, y: 16 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -8 }}
              transition={{ duration: 0.35 }}
              style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '1.6rem' }}
            >
              {filtered.map((post, i) => (
                <motion.div
                  key={post.title}
                  initial={{ opacity: 0, y: 24 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ delay: i * 0.06, duration: 0.5 }}
                  whileHover={{ y: -6, boxShadow: '0 20px 48px rgba(44,30,40,0.1)' }}
                  style={{
                    background: 'rgba(255,253,252,0.88)',
                    backdropFilter: 'blur(14px)',
                    border: '1px solid rgba(221,183,176,0.18)',
                    borderRadius: '16px',
                    overflow: 'hidden',
                    cursor: 'pointer',
                    transition: 'all 0.3s ease',
                    boxShadow: '0 2px 16px rgba(44,30,40,0.04)',
                    display: 'flex',
                    flexDirection: 'column',
                  }}
                >
                  {/* Color accent bar */}
                  <div style={{ height: '4px', background: post.color }} />

                  <div style={{ padding: '1.6rem', flex: 1, display: 'flex', flexDirection: 'column' }}>
                    {/* Tag + Icon row */}
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
                      <div style={{
                        background: '#2C1E28',
                        borderRadius: '4px',
                        padding: '3px 10px',
                        fontFamily: 'Manrope',
                        fontSize: '0.65rem',
                        fontWeight: 700,
                        color: '#EDD5D0',
                        letterSpacing: '0.07em',
                        textTransform: 'uppercase',
                      }}>
                        {post.tag}
                      </div>
                      <div style={{ fontSize: '1.35rem' }}>{post.icon}</div>
                    </div>

                    <h3 style={{
                      fontFamily: 'Cormorant Garamond, serif',
                      fontSize: '1.18rem', fontWeight: 600, color: '#2C1E28',
                      lineHeight: 1.38, marginBottom: '0.7rem',
                    }}>
                      {post.title}
                    </h3>

                    <p style={{
                      fontFamily: 'Manrope', fontSize: '0.82rem', color: '#7A606E',
                      lineHeight: 1.8, marginBottom: 'auto', paddingBottom: '1.2rem',
                    }}>
                      {post.desc}
                    </p>

                    {/* Footer */}
                    <div style={{
                      display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                      borderTop: '1px solid rgba(221,183,176,0.18)', paddingTop: '0.9rem',
                      marginTop: '0.5rem',
                    }}>
                      <span style={{ fontFamily: 'Manrope', fontSize: '0.71rem', color: '#A89098' }}>{post.date}</span>
                      <div style={{
                        display: 'flex', alignItems: 'center', gap: '0.35rem',
                        fontFamily: 'Manrope', fontSize: '0.71rem', fontWeight: 600,
                        color: '#5A3D4A', letterSpacing: '0.04em',
                      }}>
                        <span style={{ width: '14px', height: '1px', background: '#C4A89E', display: 'inline-block' }} />
                        {post.read} read
                      </div>
                    </div>
                  </div>
                </motion.div>
              ))}
            </motion.div>
          </AnimatePresence>
        </div>
      </section>

      {/* ── Newsletter Strip ── */}
      <section style={{
        padding: '80px 2rem',
        background: '#2C1E28',
        position: 'relative', zIndex: 2, overflow: 'hidden',
      }}>
        {/* Glow */}
        <div style={{
          position: 'absolute', top: '50%', left: '50%',
          transform: 'translate(-50%, -50%)',
          width: '600px', height: '300px',
          background: 'radial-gradient(ellipse, rgba(221,183,176,0.1) 0%, transparent 70%)',
          pointerEvents: 'none',
        }} />

        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          style={{ maxWidth: '600px', margin: '0 auto', textAlign: 'center', position: 'relative', zIndex: 2 }}
        >
          <div style={{
            fontFamily: 'Manrope', fontSize: '0.72rem', letterSpacing: '0.18em',
            color: '#A89098', textTransform: 'uppercase', marginBottom: '1rem',
          }}>
            Stay Connected
          </div>

          <h2 style={{
            fontFamily: 'Cormorant Garamond, serif',
            fontSize: 'clamp(1.8rem, 3.5vw, 2.6rem)',
            color: '#F5EDE8', fontWeight: 600, marginBottom: '0.9rem', lineHeight: 1.25,
          }}>
            Healing in Your Inbox
          </h2>

          <p style={{
            fontFamily: 'Manrope', fontSize: '0.9rem', color: '#B8A0AA',
            lineHeight: 1.8, marginBottom: '2rem',
          }}>
            New articles, gentle reflections, and tools for your emotional wellbeing —
            delivered twice a month, straight to you.
          </p>

          {subscribed ? (
            <motion.div
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              style={{
                background: 'rgba(237,213,208,0.12)',
                border: '1px solid rgba(237,213,208,0.25)',
                borderRadius: '10px',
                padding: '1.5rem',
                fontFamily: 'Manrope', fontSize: '0.9rem', color: '#EDD5D0',
                fontWeight: 600,
              }}
            >
              🌸 You're in — welcome to the community.
            </motion.div>
          ) : (
            <div style={{ display: 'flex', gap: '0.75rem', flexWrap: 'wrap', justifyContent: 'center' }}>
              <input
                type="email"
                placeholder="your@email.com"
                value={email}
                onChange={e => setEmail(e.target.value)}
                style={{
                  flex: '1 1 220px',
                  background: 'rgba(255,253,252,0.08)',
                  border: '1.5px solid rgba(221,183,176,0.3)',
                  borderRadius: '6px',
                  padding: '13px 18px',
                  fontFamily: 'Manrope',
                  fontSize: '0.88rem',
                  color: '#F5EDE8',
                  outline: 'none',
                  maxWidth: '320px',
                }}
                onFocus={e => e.target.style.borderColor = 'rgba(237,213,208,0.7)'}
                onBlur={e => e.target.style.borderColor = 'rgba(221,183,176,0.3)'}
              />
              <motion.button
                whileHover={{ scale: 1.04, boxShadow: '0 8px 28px rgba(0,0,0,0.35)' }}
                whileTap={{ scale: 0.97 }}
                onClick={() => email && setSubscribed(true)}
                style={{
                  background: 'linear-gradient(135deg, #EDD5D0, #D6BE8A)',
                  color: '#2C1E28',
                  border: 'none',
                  borderRadius: '6px',
                  padding: '13px 28px',
                  fontFamily: 'Manrope',
                  fontSize: '0.82rem',
                  fontWeight: 700,
                  letterSpacing: '0.07em',
                  textTransform: 'uppercase',
                  cursor: 'pointer',
                  boxShadow: '0 4px 16px rgba(0,0,0,0.2)',
                  whiteSpace: 'nowrap',
                }}
              >
                Subscribe
              </motion.button>
            </div>
          )}

          <p style={{ fontFamily: 'Manrope', fontSize: '0.7rem', color: '#6E5A62', marginTop: '1rem', letterSpacing: '0.04em' }}>
            No spam, ever. Unsubscribe with a single click.
          </p>
        </motion.div>
      </section>

    </motion.div>
  );
};

export default BlogPage;
